-- ============================================================
-- UPDATED transfer_parts: use SAVEPOINTs so failed-attempt 
-- audit rows survive the outer transaction rollback
-- ============================================================
CREATE OR REPLACE FUNCTION transfer_parts(
    source_inventory_id   INTEGER,
    target_inventory_id   INTEGER,
    part_to_transfer_num  VARCHAR,
    color_to_transfer_id  INTEGER,
    quantity_to_transfer  INTEGER,
    transfer_reason       VARCHAR DEFAULT 'manual_transfer'
)
RETURNS TEXT
LANGUAGE plpgsql
AS $$
DECLARE
    v_source_inv_exists     BOOLEAN;
    v_target_inv_exists     BOOLEAN;
    v_part_exists           BOOLEAN;
    v_color_exists          BOOLEAN;

    v_source_qty            INTEGER;
    v_source_is_spare       BOOLEAN;
    v_source_found          BOOLEAN := FALSE;
    v_target_found          BOOLEAN := FALSE;

    v_result                TEXT;
    v_error_msg             TEXT;
BEGIN
    -- =========================================================
    -- Helper: write a FAILED audit row inside its own savepoint
    -- so it is committed even when the outer txn rolls back
    -- =========================================================

    -- VALIDATION B-1: Minimum quantity
    IF quantity_to_transfer < 1 THEN
        v_error_msg := 'Quantity must be at least 1. Provided: ' || quantity_to_transfer;
        SAVEPOINT sp_audit;
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num,
            color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RELEASE SAVEPOINT sp_audit;
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- VALIDATION B-2: Maximum quantity
    IF quantity_to_transfer > 500 THEN
        v_error_msg := 'Quantity exceeds maximum limit of 500 per operation. Provided: ' || quantity_to_transfer;
        SAVEPOINT sp_audit;
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num,
            color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RELEASE SAVEPOINT sp_audit;
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- VALIDATION B-3: Self-transfer
    IF source_inventory_id = target_inventory_id THEN
        v_error_msg := 'Self-transfer not allowed. Source and target inventory IDs are both ' || source_inventory_id;
        SAVEPOINT sp_audit;
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num,
            color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RELEASE SAVEPOINT sp_audit;
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- VALIDATION A-1: Source inventory exists
    SELECT EXISTS (
        SELECT 1 FROM lego_inventories WHERE id = source_inventory_id
    ) INTO v_source_inv_exists;

    IF NOT v_source_inv_exists THEN
        v_error_msg := 'Source inventory ID ' || source_inventory_id || ' does not exist in lego_inventories.';
        SAVEPOINT sp_audit;
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num,
            color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RELEASE SAVEPOINT sp_audit;
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- VALIDATION A-2: Target inventory exists
    SELECT EXISTS (
        SELECT 1 FROM lego_inventories WHERE id = target_inventory_id
    ) INTO v_target_inv_exists;

    IF NOT v_target_inv_exists THEN
        v_error_msg := 'Target inventory ID ' || target_inventory_id || ' does not exist in lego_inventories.';
        SAVEPOINT sp_audit;
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num,
            color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RELEASE SAVEPOINT sp_audit;
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- VALIDATION A-3: Part exists
    SELECT EXISTS (
        SELECT 1 FROM lego_parts WHERE part_num = part_to_transfer_num
    ) INTO v_part_exists;

    IF NOT v_part_exists THEN
        v_error_msg := 'Part number "' || part_to_transfer_num || '" does not exist in lego_parts.';
        SAVEPOINT sp_audit;
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num,
            color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RELEASE SAVEPOINT sp_audit;
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- VALIDATION A-4: Color exists
    SELECT EXISTS (
        SELECT 1 FROM lego_colors WHERE id = color_to_transfer_id
    ) INTO v_color_exists;

    IF NOT v_color_exists THEN
        v_error_msg := 'Color ID ' || color_to_transfer_id || ' does not exist in lego_colors.';
        SAVEPOINT sp_audit;
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num,
            color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RELEASE SAVEPOINT sp_audit;
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- =========================================================
    -- STEP A: Lock source row (SELECT ... FOR UPDATE)
    -- =========================================================
    SELECT quantity, is_spare, TRUE
    INTO   v_source_qty, v_source_is_spare, v_source_found
    FROM   lego_inventory_parts
    WHERE  inventory_id = source_inventory_id
      AND  part_num     = part_to_transfer_num
      AND  color_id     = color_to_transfer_id
    FOR UPDATE;

    -- VALIDATION A-5: Part/color combination exists in source
    IF NOT v_source_found THEN
        v_error_msg := 'Source inventory ' || source_inventory_id
                    || ' does not contain part "' || part_to_transfer_num
                    || '" with color_id ' || color_to_transfer_id || '.';
        SAVEPOINT sp_audit;
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num,
            color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RELEASE SAVEPOINT sp_audit;
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- VALIDATION A-6: Sufficient quantity
    IF v_source_qty < quantity_to_transfer THEN
        v_error_msg := 'Insufficient quantity in source inventory ' || source_inventory_id
                    || '. Available: ' || v_source_qty
                    || ', Requested: ' || quantity_to_transfer
                    || ' (part: "' || part_to_transfer_num
                    || '", color_id: ' || color_to_transfer_id || ').';
        SAVEPOINT sp_audit;
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num,
            color_to_transfer_id, quantity_to_transfer, transfer_reason, 'failed', v_error_msg
        );
        RELEASE SAVEPOINT sp_audit;
        RAISE EXCEPTION '%', v_error_msg;
    END IF;

    -- Lock target row (if it exists)
    SELECT TRUE
    INTO   v_target_found
    FROM   lego_inventory_parts
    WHERE  inventory_id = target_inventory_id
      AND  part_num     = part_to_transfer_num
      AND  color_id     = color_to_transfer_id
    FOR UPDATE;

    -- =========================================================
    -- STEP B: Deduct from source inventory
    -- =========================================================
    IF v_source_qty = quantity_to_transfer THEN
        -- Exact depletion → remove the row
        DELETE FROM lego_inventory_parts
        WHERE  inventory_id = source_inventory_id
          AND  part_num     = part_to_transfer_num
          AND  color_id     = color_to_transfer_id;
    ELSE
        -- Partial deduction; preserve is_spare flag
        UPDATE lego_inventory_parts
        SET    quantity = quantity - quantity_to_transfer
        WHERE  inventory_id = source_inventory_id
          AND  part_num     = part_to_transfer_num
          AND  color_id     = color_to_transfer_id;
    END IF;

    -- =========================================================
    -- STEP C: Credit to target inventory
    -- =========================================================
    IF v_target_found THEN
        -- Already has this part/color → increment
        UPDATE lego_inventory_parts
        SET    quantity = quantity + quantity_to_transfer
        WHERE  inventory_id = target_inventory_id
          AND  part_num     = part_to_transfer_num
          AND  color_id     = color_to_transfer_id;
    ELSE
        -- New part for this inventory → insert, inheriting is_spare
        INSERT INTO lego_inventory_parts
               (inventory_id, part_num, color_id, quantity, is_spare)
        VALUES (target_inventory_id, part_to_transfer_num, color_to_transfer_id,
                quantity_to_transfer, v_source_is_spare);
    END IF;

    -- =========================================================
    -- STEP D: Audit log — success (no savepoint needed here)
    -- =========================================================
    INSERT INTO inventory_transfer_log (
        source_inventory_id, target_inventory_id, part_num, color_id,
        quantity_transferred, transfer_reason, transfer_status, error_message
    ) VALUES (
        source_inventory_id, target_inventory_id, part_to_transfer_num,
        color_to_transfer_id, quantity_to_transfer, transfer_reason, 'success', NULL
    );

    -- =========================================================
    -- Build and return success message
    -- =========================================================
    v_result := 'Successfully transferred ' || quantity_to_transfer
             || ' parts (' || part_to_transfer_num
             || ', color_id: ' || color_to_transfer_id
             || ') from inventory ' || source_inventory_id
             || ' to inventory '   || target_inventory_id
             || '. Reason: '       || transfer_reason;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RAISE;
END;
$$;
"}

