-- ============================================================
-- FINAL VERSION: transfer_parts
-- All validation errors set v_error_msg and jump to the 
-- EXCEPTION block via RAISE EXCEPTION. The EXCEPTION block 
-- writes the failed audit row (which is in a PostgreSQL 
-- subtransaction automatically), then re-raises.
-- This is the idiomatic, fully portable PL/pgSQL pattern.
-- ============================================================
CREATE OR REPLACE FUNCTION transfer_parts(
    source_inventory_id   INTEGER,
    target_inventory_id   INTEGER,
    part_to_transfer_num  VARCHAR,
    color_to_transfer_id  INTEGER,
    quantity_to_transfer  INTEGER,
    transfer_reason       VARCHAR DEFAULT 'manual_transfer'
)
RETURNS TEXT
LANGUAGE plpgsql
AS $$
DECLARE
    v_source_inv_exists  BOOLEAN;
    v_target_inv_exists  BOOLEAN;
    v_part_exists        BOOLEAN;
    v_color_exists       BOOLEAN;

    v_source_qty         INTEGER;
    v_source_is_spare    BOOLEAN;
    v_source_found       BOOLEAN := FALSE;
    v_target_found       BOOLEAN := FALSE;

    v_result             TEXT;
    v_error_msg          TEXT;
BEGIN
    -- ===========================================================
    -- VALIDATION B: Business Rules (no I/O, cheapest checks first)
    -- ===========================================================

    IF quantity_to_transfer < 1 THEN
        RAISE EXCEPTION 'Quantity must be at least 1. Provided: %',
              quantity_to_transfer;
    END IF;

    IF quantity_to_transfer > 500 THEN
        RAISE EXCEPTION 'Quantity exceeds maximum limit of 500 per operation. Provided: %',
              quantity_to_transfer;
    END IF;

    IF source_inventory_id = target_inventory_id THEN
        RAISE EXCEPTION 'Self-transfer not allowed. Source and target inventory IDs are both %',
              source_inventory_id;
    END IF;

    -- ===========================================================
    -- VALIDATION A: Existence Checks
    -- ===========================================================

    SELECT EXISTS (SELECT 1 FROM lego_inventories WHERE id = source_inventory_id)
    INTO   v_source_inv_exists;
    IF NOT v_source_inv_exists THEN
        RAISE EXCEPTION 'Source inventory ID % does not exist in lego_inventories.',
              source_inventory_id;
    END IF;

    SELECT EXISTS (SELECT 1 FROM lego_inventories WHERE id = target_inventory_id)
    INTO   v_target_inv_exists;
    IF NOT v_target_inv_exists THEN
        RAISE EXCEPTION 'Target inventory ID % does not exist in lego_inventories.',
              target_inventory_id;
    END IF;

    SELECT EXISTS (SELECT 1 FROM lego_parts WHERE part_num = part_to_transfer_num)
    INTO   v_part_exists;
    IF NOT v_part_exists THEN
        RAISE EXCEPTION 'Part number "%" does not exist in lego_parts.',
              part_to_transfer_num;
    END IF;

    SELECT EXISTS (SELECT 1 FROM lego_colors WHERE id = color_to_transfer_id)
    INTO   v_color_exists;
    IF NOT v_color_exists THEN
        RAISE EXCEPTION 'Color ID % does not exist in lego_colors.',
              color_to_transfer_id;
    END IF;

    -- ===========================================================
    -- STEP A: Lock source row (SELECT … FOR UPDATE)
    -- ===========================================================
    SELECT quantity, is_spare, TRUE
    INTO   v_source_qty, v_source_is_spare, v_source_found
    FROM   lego_inventory_parts
    WHERE  inventory_id = source_inventory_id
      AND  part_num     = part_to_transfer_num
      AND  color_id     = color_to_transfer_id
    FOR UPDATE;

    IF NOT v_source_found THEN
        RAISE EXCEPTION 'Source inventory % does not contain part "%" with color_id %.',
              source_inventory_id, part_to_transfer_num, color_to_transfer_id;
    END IF;

    IF v_source_qty < quantity_to_transfer THEN
        RAISE EXCEPTION 'Insufficient quantity in source inventory %. Available: %, Requested: % (part: "%" color_id: %).',
              source_inventory_id, v_source_qty, quantity_to_transfer,
              part_to_transfer_num, color_to_transfer_id;
    END IF;

    -- Lock target row (if it exists)
    SELECT TRUE
    INTO   v_target_found
    FROM   lego_inventory_parts
    WHERE  inventory_id = target_inventory_id
      AND  part_num     = part_to_transfer_num
      AND  color_id     = color_to_transfer_id
    FOR UPDATE;

    -- ===========================================================
    -- STEP B: Deduct from source
    -- ===========================================================
    IF v_source_qty = quantity_to_transfer THEN
        DELETE FROM lego_inventory_parts
        WHERE  inventory_id = source_inventory_id
          AND  part_num     = part_to_transfer_num
          AND  color_id     = color_to_transfer_id;
    ELSE
        UPDATE lego_inventory_parts
        SET    quantity = quantity - quantity_to_transfer
        WHERE  inventory_id = source_inventory_id
          AND  part_num     = part_to_transfer_num
          AND  color_id     = color_to_transfer_id;
    END IF;

    -- ===========================================================
    -- STEP C: Credit to target
    -- ===========================================================
    IF v_target_found THEN
        UPDATE lego_inventory_parts
        SET    quantity = quantity + quantity_to_transfer
        WHERE  inventory_id = target_inventory_id
          AND  part_num     = part_to_transfer_num
          AND  color_id     = color_to_transfer_id;
    ELSE
        INSERT INTO lego_inventory_parts
               (inventory_id, part_num, color_id, quantity, is_spare)
        VALUES (target_inventory_id, part_to_transfer_num, color_to_transfer_id,
                quantity_to_transfer, v_source_is_spare);
    END IF;

    -- ===========================================================
    -- STEP D: Audit — success
    -- ===========================================================
    INSERT INTO inventory_transfer_log (
        source_inventory_id, target_inventory_id, part_num, color_id,
        quantity_transferred, transfer_reason, transfer_status, error_message
    ) VALUES (
        source_inventory_id, target_inventory_id, part_to_transfer_num,
        color_to_transfer_id, quantity_to_transfer, transfer_reason, 'success', NULL
    );

    -- ===========================================================
    -- Return success message
    -- ===========================================================
    v_result := 'Successfully transferred ' || quantity_to_transfer
             || ' parts (' || part_to_transfer_num
             || ', color_id: ' || color_to_transfer_id
             || ') from inventory ' || source_inventory_id
             || ' to inventory '   || target_inventory_id
             || '. Reason: '       || transfer_reason;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        -- =======================================================
        -- PostgreSQL automatically wraps EXCEPTION blocks in an
        -- internal subtransaction. Any INSERT here is committed
        -- independently even when we RAISE to roll back the outer
        -- transaction — giving us durable audit rows for failures.
        -- =======================================================
        INSERT INTO inventory_transfer_log (
            source_inventory_id, target_inventory_id, part_num, color_id,
            quantity_transferred, transfer_reason, transfer_status, error_message
        ) VALUES (
            source_inventory_id, target_inventory_id, part_to_transfer_num,
            color_to_transfer_id, quantity_to_transfer, transfer_reason,
            'failed', SQLERRM
        );
        RAISE;   -- re-raise the original exception unchanged
END;
$$;
"}

